CREATE TABLE IF NOT EXISTS local_rbac_group (id VARCHAR(36) PRIMARY KEY, name VARCHAR(128) NOT NULL UNIQUE, revision BIGINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS local_rbac_member (group_id VARCHAR(36) NOT NULL, account_id BIGINT NOT NULL, PRIMARY KEY(group_id,account_id), KEY(account_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS local_rbac_grant (group_id VARCHAR(36) NOT NULL, project_id BIGINT NOT NULL, role VARCHAR(16) NOT NULL, PRIMARY KEY(group_id,project_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS local_rbac_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor BIGINT NOT NULL, group_id VARCHAR(36) NOT NULL, operation VARCHAR(16) NOT NULL, created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS local_rbac_audit_detail (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor BIGINT NOT NULL, group_id VARCHAR(36) NOT NULL, operation VARCHAR(16) NOT NULL, before_snapshot MEDIUMTEXT NULL, after_snapshot MEDIUMTEXT NULL, created TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY(group_id,id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS local_rbac_oidc_user (identity_hash VARCHAR(64) PRIMARY KEY, account_id BIGINT NOT NULL UNIQUE) ENGINE=InnoDB;
